package fable.hideseek.imba.client;

import fable.hideseek.imba.net.MaskNetworking;import fable.hideseek.imba.net.WallClimbNetworking;import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;import net.fabricmc.fabric.api.client.keybinding.v1.KeyBindingHelper;import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking;import net.fabricmc.fabric.api.networking.v1.PacketByteBufs;import net.minecraft.client.option.KeyBinding;import net.minecraft.client.util.InputUtil;import net.minecraft.util.hit.HitResult;import net.minecraft.util.hit.BlockHitResult;import org.lwjgl.glfw.GLFW;
public class KeyBindings{public static KeyBinding rotateKey,rotateXKey,rotateZKey,wallClimbKey;private static boolean attackPressedLastTick,usePressedLastTick;public static void register(){rotateKey=KeyBindingHelper.registerKeyBinding(new KeyBinding("key.imba.rotate",InputUtil.Type.KEYSYM,GLFW.GLFW_KEY_R,"category.imba.mask"));rotateXKey=KeyBindingHelper.registerKeyBinding(new KeyBinding("key.imba.rotate_x",InputUtil.Type.KEYSYM,GLFW.GLFW_KEY_X,"category.imba.mask"));rotateZKey=KeyBindingHelper.registerKeyBinding(new KeyBinding("key.imba.rotate_z",InputUtil.Type.KEYSYM,GLFW.GLFW_KEY_Z,"category.imba.mask"));wallClimbKey=KeyBindingHelper.registerKeyBinding(new KeyBinding("key.imba.wall_climb",InputUtil.Type.KEYSYM,GLFW.GLFW_KEY_C,"category.imba.mask"));ClientTickEvents.END_CLIENT_TICK.register(client->{if(client.player==null){attackPressedLastTick=false;usePressedLastTick=false;return;}while(rotateKey.wasPressed())if(ClientGameState.isHider()&&ClientMaskData.hasMask(client.player.getUuid()))ClientPlayNetworking.send(MaskNetworking.ROTATE_PACKET,PacketByteBufs.empty());while(rotateXKey.wasPressed())if(ClientGameState.isHider()&&ClientMaskData.hasMask(client.player.getUuid())){var b=PacketByteBufs.create();b.writeString("x");ClientPlayNetworking.send(MaskNetworking.ROTATE_AXIS_PACKET,b);}while(rotateZKey.wasPressed())if(ClientGameState.isHider()&&ClientMaskData.hasMask(client.player.getUuid())){var b=PacketByteBufs.create();b.writeString("z");ClientPlayNetworking.send(MaskNetworking.ROTATE_AXIS_PACKET,b);}while(wallClimbKey.wasPressed())if(ClientGameState.isHider()&&ClientMaskData.hasMask(client.player.getUuid()))ClientPlayNetworking.send(WallClimbNetworking.TOGGLE,PacketByteBufs.empty());boolean attackNow=client.options.attackKey.isPressed(),useNow=client.options.useKey.isPressed();if(client.currentScreen==null){if(attackNow&&!attackPressedLastTick){if(client.crosshairTarget instanceof BlockHitResult hit){var b=PacketByteBufs.create();b.writeBlockPos(hit.getBlockPos());ClientPlayNetworking.send(MaskNetworking.SEEKER_BLOCK_ATTACK_PACKET,b);}else if(client.crosshairTarget==null||client.crosshairTarget.getType()==HitResult.Type.MISS)ClientPlayNetworking.send(MaskNetworking.SEEKER_MISS_PACKET,PacketByteBufs.empty());}if(useNow&&!usePressedLastTick)ClientPlayNetworking.send(MaskNetworking.SEEKER_USE_PACKET,PacketByteBufs.empty());}attackPressedLastTick=attackNow;usePressedLastTick=useNow;});}}
